import { GameScene } from "../modules";

export const createAlphaTween = (
  scene: GameScene,
  target: {
    alpha: number;
    setAlpha: (v: number) => any;
  },
  type: "show" | "hide",
  onComplete?: () => void,
) => {
  const startAlpha = target.alpha || type === "hide" ? 1 : 0,
    finalAlpha = type === "hide" ? 0 : 1;

  const destroyTween = scene.tweens.add({
    targets: { alpha: startAlpha },
    alpha: finalAlpha,
    duration: 1000,
    onUpdate: (event) => {
      try {
        console.log(target.alpha);

        const current = event.targets[0] as { alpha: number };
        target.setAlpha(current.alpha);
      } catch {}
    },
    onComplete: () => {
      onComplete && onComplete();
    },
  });

  return destroyTween;
};
